#include <cuda_runtime.h>

__global__ void matrix_mul_vectorized_kernel(const float* A, const float* B, float* C, int N) {
    __shared__ float4 sA[32][8];  // 32x32 tile with 4 elements per thread
    __shared__ float4 sB[32][8];

    int row = blockIdx.y * blockDim.y + threadIdx.y;
    int col = blockIdx.x * blockDim.x + threadIdx.x;

    float sum = 0.0f;

    for (int tile = 0; tile < N / 32; ++tile) {
        // Load tiles of A and B into shared memory using float4
        sA[threadIdx.y][threadIdx.x / 4] = reinterpret_cast<const float4*>(A)[row * (N / 4) + (tile * 8 + threadIdx.x / 4)];
        sB[threadIdx.y][threadIdx.x / 4] = reinterpret_cast<const float4*>(B)[(tile * 8 + threadIdx.y) * (N / 4) + col / 4];
        __syncthreads();

        // Compute partial sum with vectorized loads
        for (int k = 0; k < 8; ++k) {
            float4 a = sA[threadIdx.y][k];
            float4 b = sB[k][threadIdx.x / 4];
            sum += a.x * b.x;
            sum += a.y * b.y;
            sum += a.z * b.z;
            sum += a.w * b.w;
        }
        __syncthreads();
    }

